"""Generate a reviewable immutable-version database catalog; never connect."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
TARGET=ROOT/'supabase/migrations/20261108000003_quiz_catalog.sql'
def literal(value):return "'"+str(value).replace("'","''")+"'"
def render():
    b=json.loads((ROOT/'web/content/quizzes/bank.json').read_text())
    items=[f"({literal(q['item_id'])},{literal(q['content_version'])},{literal(q['pool_id'])},{literal(q['answer'])},'{json.dumps([o['id'] for o in q['options']],separators=(',',':'))}'::jsonb,true)" for q in b['items']]
    assessments=[f"({literal(a['assessment_id'])},{literal(a['content_version'])},{literal(a['item_version'])},'{json.dumps(a['pool_ids'],separators=(',',':'))}'::jsonb,true)" for a in b['assessments']]
    return '-- Generated by scripts/seed_quizzes.py; published versions are immutable.\nbegin;\ninsert into public.quiz_items_v1 (item_id,content_version,pool_id,answer,option_ids,published) values\n'+',\n'.join(items)+'\non conflict (item_id,content_version) do nothing;\ninsert into public.quiz_catalog_v1 (assessment_id,content_version,item_version,pool_ids,published) values\n'+',\n'.join(assessments)+'\non conflict (assessment_id,content_version) do nothing;\ncommit;\n'
if __name__=='__main__':TARGET.write_text(render());print(TARGET.relative_to(ROOT))
